def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    def opp_at(i):
        return history[i][1]

    def me_at(i):
        return history[i][0]

    c_opp = sum(1 for i in range(n) if opp_at(i) == 'C')
    d_opp = n - c_opp
    coop_rate = c_opp / n

    # Constant detection
    if d_opp == 0:
        # Exploit late, otherwise cooperate
        if 100 - n <= 6:
            return 'D'
        return 'C'
    if c_opp == 0:
        return 'D'

    # Endgame exploitation only when opponent is reliably cooperative
    remaining = 100 - n
    if remaining <= 4:
        if coop_rate >= 0.7:
            return 'D'
        if coop_rate >= 0.5:
            return 'C'
        return 'D'

    # Recent window (last 8)
    w = min(8, n)
    rec_c = sum(1 for i in range(n - w, n) if opp_at(i) == 'C')
    rec_d = w - rec_c

    # Defection streak
    streak_d = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'D':
        streak_d += 1
        i -= 1

    # Cooperation streak
    streak_c = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'C':
        streak_c += 1
        i -= 1

    # Aggressive opponents: defect hard
    if rec_d >= 6:
        return 'D'
    if rec_d >= 4 and coop_rate < 0.5:
        return 'D'

    # Mostly cooperative opponent - cooperate, occasional rare probe
    if coop_rate >= 0.85 and rec_d <= 1:
        if streak_d == 0 and n > 25 and n < 90 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # After a defection streak: mostly defect, but forgive if opponent has good history
    if streak_d >= 3:
        # If opponent is generally cooperative, give a forgiveness chance
        if coop_rate >= 0.75 and streak_d == 3 and rec_d <= 3:
            if rng.random() < 0.4:
                return 'C'
        return 'D'
    if streak_d == 2:
        if coop_rate >= 0.8:
            return 'C'
        return 'D'
    if streak_d == 1:
        # Single defection - punish once, forgive if history good
        if coop_rate >= 0.75:
            # Tit-for-tat: we cooperated, they defected, defect once
            if me_at(n - 1) == 'C':
                return 'D'
            return 'C'
        if coop_rate >= 0.55 and rec_d <= 1:
            return 'C'
        return 'D'

    # Opponent cooperated last. If we defected, return to cooperation quickly
    # to avoid triggering long retaliation (important vs TFT)
    if me_at(n - 1) == 'D':
        # Return to C unless opponent looks exploitable
        if coop_rate >= 0.5:
            return 'C'
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # Detect TFT-like opponent: they mirror our previous move
    if n >= 8:
        mirror = 0
        checks = min(n - 1, 15)
        for i in range(n - checks, n):
            if i >= 1 and opp_at(i) == me_at(i - 1):
                mirror += 1
        if mirror >= checks * 0.75:
            # Play C to keep cooperation going (mutual C = 3 > alternation)
            return 'C'

    # Default: cooperate when opponent recently cooperative
    if rec_d <= 1:
        # occasional defection when opponent is highly cooperative
        if coop_rate >= 0.7 and rec_d == 0 and 10 < n < 85 and rng.random() < 0.06:
            return 'D'
        return 'C'

    if rec_d <= 3:
        if coop_rate >= 0.6:
            return 'C'
        return 'D'

    return 'D'
